   741  H3Error H3_EXPORT(maxPolygonToCellsSizeExperimental)(const GeoPolygon *polygon,
   742                                                       int res, uint32_t flags,
   743                                                       int64_t *out) {
   744      // Special case: 0-vertex polygon
   745      if (polygon->geoloop.numVerts == 0) {
   746          *out = 0;
   747          return E_SUCCESS;
   748      }
   749
   750      // Initialize the iterator without stepping, so we can adjust the res and
   751      // flags (after they are validated by the initialization) before we start
   752      IterCellsPolygonCompact iter = _iterInitPolygonCompact(polygon, res, flags);
   753
   754      if (iter.error) {
   755          return iter.error;
   756      }
   757
   758      // Ignore the requested flags and use the faster overlapping-bbox mode
   759      iter._flags = CONTAINMENT_OVERLAPPING_BBOX;
   760
